package net.civeira.phylax.features.oauth.delegatelogin.infrastructure.driven;

import java.util.List;
import java.util.Optional;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.features.oauth.delegatelogin.domain.DelegatedAccessExternalProvider;
import net.civeira.phylax.features.oauth.delegatelogin.domain.FederatedUser;
import net.civeira.phylax.features.oauth.delegatelogin.domain.PendingDelegation;
import net.civeira.phylax.features.oauth.delegatelogin.domain.gateway.DelegateLoginGateway;
import net.civeira.phylax.features.oauth.delegatelogin.domain.gateway.DelegatedAccessProviderGateway;
import net.civeira.phylax.features.oauth.delegatelogin.domain.gateway.DelegatedStoreGateway;

/**
 * Adapter that bridges the unified DelegateLoginGateway to legacy gateways.
 *
 * Responsibilities: - Delegate pending login storage to DelegatedStoreGateway. - Delegate provider
 * lookup and account resolution to DelegatedAccessProviderGateway.
 *
 * Design notes: - Provides backward compatibility for existing gateways. - Keeps unified gateway
 * contract simple.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class DelegateLoginAdapter implements DelegateLoginGateway {

  /**
   * Legacy store for pending logins.
   */
  private final DelegatedStoreGateway store;
  /**
   * Legacy provider registry and account resolver.
   */
  private final DelegatedAccessProviderGateway validator;

  @Override
  public void savePending(String stateHash, PendingDelegation pending) {
    store.save(stateHash, pending);
  }

  @Override
  public Optional<PendingDelegation> findPending(String stateHash) {
    return store.find(stateHash);
  }

  @Override
  public Optional<PendingDelegation> consumePending(String tenant, String stateHash) {
    return store.consume(tenant, stateHash);
  }

  @Override
  public List<DelegatedAccessExternalProvider> providers(AuthRequest request) {
    return validator.providers(request);
  }

  @Override
  public Optional<String> resolveAccount(AuthRequest request, String provider, FederatedUser user) {
    return validator.resolveAccount(request, provider, user);
  }
}
